insert into public.messages (community_id, sender_id, content, message_type) select 1, null, 'Chào mừng bạn đến với Cộng đồng Chó! Hãy giữ thái độ tôn trọng, không quảng cáo, không chia sẻ thông tin cá nhân. Xem mục Wiki để đọc hướng dẫn chăm sóc và Bộ sưu tập để tìm ảnh đẹp nhé.', 'SYSTEM' where not exists (select 1 from public.messages where community_id = 1);
